'use strict';
let workGenre='all',workComparisonIds=[];
const openWorkIds=new Set();
function philosophyWorks(){return comparisonReaderData.cultureWorks||[];}
function workById(id){return philosophyWorks().find(w=>w.id===id);}
function validWorkSelection(value){return Array.isArray(value)?Array.from(new Set(value.filter(id=>typeof id==='string'&&workById(id)))).slice(0,2):[];}
function loadWorkComparison(){try{workComparisonIds=validWorkSelection(JSON.parse(localStorage.getItem('yanguang:work-comparison:v1')));}catch{workComparisonIds=[];}}
function setWorkComparison(id){
 if(!workById(id))return;const selected=workComparisonIds.includes(id);if(!selected&&workComparisonIds.length===2)return;
 workComparisonIds=selected?workComparisonIds.filter(i=>i!==id):[...workComparisonIds,id];saveWorkComparison();renderComparisonReader();const button=$('#reader-content').querySelector(`[data-work-toggle="${id}"]`);(button||$('#work-genre'))?.focus({preventScroll:true});button?.scrollIntoView({block:'nearest'});
}
function saveWorkComparison(){try{localStorage.setItem('yanguang:work-comparison:v1',JSON.stringify(workComparisonIds));}catch{/* Comparison stays available in this page without storage. */}}
function workSourcesLink(entry){const source=entry.sources.find(s=>s.kind==='原典旧英译入口')||entry.sources.find(s=>s.kind==='现代化改写的原典入口')||entry.sources[0],label=source.kind==='原典旧英译入口'?'阅读原典旧英译 ↗':source.kind==='现代化改写的原典入口'?'阅读现代便读改写 ↗':'查看著作研究与书目 ↗';return readerLink(label,source.url);}
function workActionButton(label,action){const b=historyEl('button',label,'reader-save');b.type='button';b.addEventListener('click',action);return b;}
function renderWorkComparison(root){
 if(!workComparisonIds.length)return;const panel=historyEl('section',null,'work-comparison');panel.id='work-comparison-panel';panel.setAttribute('aria-label','两部著作并列对读');const header=historyEl('div',null,'work-comparison-heading');header.append(historyEl('h3',`两部著作对读 · ${workComparisonIds.length}/2`),workActionButton('清空对读',()=>{workComparisonIds=[];saveWorkComparison();renderComparisonReader();$('#work-genre')?.focus({preventScroll:true});}));panel.append(header,historyEl('p','这是跨年代的问题比较；各书独列写作与出版信息，不据主题相似就断言直接影响，也不将两书配成当前中国年份的同时事件。','reader-notice'));
 const grid=historyEl('div',null,'work-comparison-grid');for(const id of workComparisonIds){const w=workById(id),column=historyEl('section',null,'work-comparison-column');column.dataset.comparedWork=id;column.append(historyEl('p',w.genre,'reader-entry-meta'),historyEl('h4',w.title),readerPeopleLinks(w.people),historyEl('p',w.attribution,'work-attribution'),historyEl('p',w.dateLabel,'work-date'),historyEl('small',w.publicationLabel));for(const [label,value] of [['核心问题',w.argument],['论证方向',w.sections[1].text],['先读哪里',w.passages[0].locator+' · '+w.passages[0].prompt],['保留区别',w.misreading.correction]])column.append(historyEl('h5',label),historyEl('p',value));column.append(workActionButton('打开完整导读 ↗',()=>focusReaderEntity('culture',id)),workActionButton('移除此书',()=>setWorkComparison(id)),readerSources(w));grid.append(column);}if(workComparisonIds.length===1)grid.append(historyEl('p','再从下方选择一部作品，便可比较两边的问题、论证及阅读入口。','reader-empty'));panel.append(grid);
 if(workComparisonIds.length===2){const [a,b]=workComparisonIds.map(workById),shared=a.questionIds.filter(id=>b.questionIds.includes(id));panel.append(historyEl('h4',shared.length?'共同的已编选问题':'换个角度比较'));if(shared.length)panel.append(cultureLinks(shared));else panel.append(historyEl('p','目前没有共同的问题标签，可从写作语境、使用证据及结论边界比较。标签差异不证明不存在思想联系。'));}root.append(panel);
}
function philosophyWorkCard(entry,query,single){
 const card=historyEl('article',null,'reader-entry reader-essay work-card');card.dataset.readerCulture=entry.id;card.append(historyEl('p',entry.genre+' · '+entry.dateLabel,'reader-entry-meta'),historyEl('h3',entry.title),historyEl('p',entry.originalTitle,'work-original-title'),readerPeopleLinks(entry.people),historyEl('p',entry.attribution,'work-attribution'),historyEl('p',entry.argument,'work-question'),historyEl('p','版本与传播：'+entry.publicationLabel,'work-publication'));
 if(entry.range[0]>readerYear)card.append(historyEl('p','此书晚于浏览年；本页为跨年代著作阅读。','reader-notice'));
 if(typeof philosophyGalleryData!=='undefined')card.append(philosophyGallery(philosophyGalleryData.filter(i=>i.workIds.includes(entry.id)).map(i=>i.id)));
 const actions=historyEl('div',null,'work-actions'),selected=workComparisonIds.includes(entry.id),toggle=workActionButton(selected?'已选入对读 · 移除':workComparisonIds.length===2?'对读已满 · 先移除一部':'加入两部对读',()=>setWorkComparison(entry.id));toggle.dataset.workToggle=entry.id;toggle.setAttribute('aria-pressed',String(selected));toggle.disabled=!selected&&workComparisonIds.length===2;actions.append(toggle,workSourcesLink(entry));if(workComparisonIds.length===2)actions.append(workActionButton('查看两部对读 ↑',()=>$('#work-comparison-panel').scrollIntoView({block:'start'})));card.append(actions);
 const details=historyEl('details',null,'reader-work-body');details.open=openWorkIds.has(entry.id)||(Boolean(query)&&single);details.append(historyEl('summary','展开语境、论证、章节路径与误读辨析'));details.addEventListener('toggle',()=>{if(!details.isConnected)return;if(details.open)openWorkIds.add(entry.id);else openWorkIds.delete(entry.id);});details.querySelector('summary').addEventListener('click',()=>{if(!details.open)rememberReader('culture',entry.id);});
 for(const s of entry.sections)details.append(historyEl('h4',s.title),historyEl('p',s.text));details.append(historyEl('h4','带着问题读原文'));const list=historyEl('ol',null,'work-passages');for(const p of entry.passages){const li=historyEl('li');li.append(historyEl('strong',p.locator),historyEl('p',p.prompt));list.append(li);}details.append(list);const warning=historyEl('section',null,'work-misreading');warning.append(historyEl('h4','常见误读与修正'),historyEl('p','容易误读：'+entry.misreading.claim),historyEl('p','需要区分：'+entry.misreading.correction));details.append(warning);
 if(entry.questionIds.length)details.append(historyEl('h4','继续追问'),cultureLinks(entry.questionIds));if(entry.relatedCultureIds.length)details.append(historyEl('h4','回到相关文化纪事与前史'),cultureLinks(entry.relatedCultureIds));details.append(readerSources(entry),readerSaveButton('culture',entry.id));card.append(details);return card;
}
function renderPhilosophyWorks(root,query){
 root.append(historyEl('p','从具体作品进入思想。成文、编纂、首次印刷与后世译本分别记录；公元前作品的约年不接入主年轴。此页跨年代检索，不把作品一律当成一次出版事件。','reader-notice'));
 const controls=historyEl('div',null,'philosophy-controls work-controls'),label=historyEl('label','阅读领域 '),select=historyEl('select');select.id='work-genre';select.setAttribute('aria-label','著作阅读领域');select.append(new Option('全部领域','all'));for(const genre of new Set(philosophyWorks().map(w=>w.genre)))select.append(new Option(genre,genre));select.value=workGenre;select.addEventListener('change',()=>{workGenre=select.value;renderComparisonReader();});label.append(select);const count=historyEl('span',`已选 ${workComparisonIds.length}/2 部 · 对读选择仅保存在本机`,'work-selection-status');count.setAttribute('role','status');controls.append(label,count);if(workComparisonIds.length)controls.append(workActionButton('查看已选对读 ↓',()=>$('#work-comparison-panel').scrollIntoView({block:'start'})));root.append(controls);renderWorkComparison(root);
 const entries=philosophyWorks().filter(w=>(workGenre==='all'||w.genre===workGenre)&&readerMatches(w,query));for(const entry of entries)root.append(philosophyWorkCard(entry,query,entries.length===1));if(!entries.length)root.append(historyEl('p','当前领域和关键词下没有匹配的著作。可清除关键词或改为全部领域；已选对读保留在上方。','reader-empty'));return entries.length;
}
